id":"synthetic-existing-proof","evidence_text":"Invented prior evidence only"}}},"after":{"id":"00000000-0000-0000-0000-000000000067","user_id":"00000000-0000-0000-0000-000000000099","source_record_id":"synthetic-marker-67","biomarker":"Synthetic marker 67","collection_date":"2025-01-15","report_date":"2025-01-15","result_raw":"67","result_numeric":67,"unit":"synthetic-unit","method":"Synthetic retained method","laboratory":"Synthetic laboratory","source":"Synthetic fixture","source_file":"synthetic.pdf","flag":null,"confidence":"synthetic","notes":"Synthetic fixture only","created_at":"2025-01-15T00:00:00+00:00","reference_range":"67 a 167 synthetic-unit","source_payload":{"retained":{"nested":["invented",67,true,null]},"numeric_kind":"exact","method_verification":{"audit_id":"synthetic-existing-proof","evidence_text":"Invented prior evidence only"},"pdf_page":67,"library_file_id":"synthetic-library-file","reference_verification":{"audit_id":"synthetic-reference-proof","pdf_page":67,"evidence_text":"Invented reference evidence 67","reference_text":"67 a 167 synthetic-unit"}}}}]$review_rows$::jsonb;
  target jsonb;
  current_row jsonb;
  changed_count integer;
  total_changed integer := 0;
BEGIN
  IF jsonb_array_length(targets) <> 67 OR
     (SELECT count(DISTINCT value->'before'->>'id') FROM jsonb_array_elements(targets)) <> 67 THEN
    RAISE EXCEPTION 'Expected exactly 67 distinct reviewed targets';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.health_lab_results'::regclass AND NOT tgisinternal) THEN
    RAISE EXCEPTION 'Trigger configuration changed; review write side effects first';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_rewrite WHERE ev_class='public.health_lab_results'::regclass AND rulename<>'_RETURN') THEN
    RAISE EXCEPTION 'Rewrite rule configuration changed; review write side effects first';
  END IF;
  -- Lock and validate every row before the first update.
  FOR target IN SELECT value FROM jsonb_array_elements(targets) ORDER BY value->'before'->>'id' LOOP
    SELECT to_jsonb(l) INTO current_row FROM public.health_lab_results AS l
      WHERE l.id=(target->'before'->>'id')::uuid
        AND l.user_id=(target->'before'->>'user_id')::uuid
      FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Reviewed target missing or owner mismatch'; END IF;
    IF current_row IS DISTINCT FROM target->'before' AND current_row IS DISTINCT FROM target->'after' THEN
      RAISE EXCEPTION 'Reviewed target changed; refresh preimage and review again';
    END IF;
  END LOOP;
  FOR target IN SELECT value FROM jsonb_array_elements(targets) ORDER BY value->'before'->>'id' LOOP
    SELECT to_jsonb(l) INTO current_row FROM public.health_lab_results AS l
      WHERE l.id=(target->'before'->>'id')::uuid AND l.user_id=(target->'before'->>'user_id')::uuid;
    IF current_row = target->'after' THEN
      UPDATE public.health_lab_results AS l
        SET method=target->'before'->>'method',
            reference_range=target->'before'->>'reference_range',
            source_payload=CASE WHEN target->'before'->'source_payload'='null'::jsonb THEN NULL ELSE target->'before'->'source_payload' END
        WHERE l.id=(target->'before'->>'id')::uuid
          AND l.user_id=(target->'before'->>'user_id')::uuid
          AND to_jsonb(l)=target->'after';
      GET DIAGNOSTICS changed_count = ROW_COUNT;
      IF changed_count <> 1 THEN RAISE EXCEPTION 'Conditional write did not change exactly one target'; END IF;
      total_changed := total_changed + changed_count;
    END IF;
  END LOOP;
  FOR target IN SELECT value FROM jsonb_array_elements(targets) LOOP
    SELECT to_jsonb(l) INTO current_row FROM public.health_lab_results AS l
      WHERE l.id=(target->'before'->>'id')::uuid AND l.user_id=(target->'before'->>'user_id')::uuid;
    IF NOT FOUND OR current_row IS DISTINCT FROM target->'before' THEN
      RAISE EXCEPTION 'Exact postcondition failed; rollback transaction';
    END IF;
  END LOOP;
  RAISE NOTICE 'Reviewed metadata rollback: changed %, total targets 67', total_changed;
END;
$review$;
COMMIT;
